"""Памятки готовой лабораторной, только по фактическим данным проверки."""
from pathlib import Path
import json
from lab10_content import TASKS,QUESTIONS,PLACEHOLDERS
ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'output/lab10';WORK=ROOT/'work/lab10'
qa=json.loads((WORK/'model-qa.json').read_text(encoding='utf-8'));manifest=json.loads((WORK/'report-manifest.json').read_text(encoding='utf-8'));assert qa['passed']
nums={f['key']:f['number'] for f in manifest['figures']};scenes={x['number']:x for x in json.loads((WORK/'scenes.json').read_text(encoding='utf-8'))}
parts=['# Лабораторная 10 — шпаргалка к защите',
'Внутренний номер 15 в методичке не является номером этой работы. Все результаты оформлены как лабораторная 10. Модель создана в Blender 5.2.1 LTS через Python API.',
'## Как открыть и показывать',
'1. Открой `Лаба10_Blender.blend`. Разрешать Auto Run Python Scripts не требуется. Выбирай нужную сцену в верхней панели Blender; номер сцены совпадает с номером задания. F12 строит итоговый кадр в проверенном EEVEE.',
'2. Выбери основной объект в Outliner и открой «Модификаторы» (значок гаечного ключа). Узловые модификаторы показывают исходные параметры из методички. У них нет требования устанавливать дополнения.',
'3. В Outliner коллекция «Этапы N (скрыто)» исключена из слоя. Для сравнения временно включи её флажком, скрой мешающие итоговые объекты значком глаза; после демонстрации верни прежнюю видимость. Для F12 нужно также временно включить рендер этапов значком камеры. Сохранять эти изменения поверх выдаваемого файла не обязательно.',
'4. Для узлового аналога можно открыть рабочую область «Ноды геометрии» и выбрать группу нужного модификатора. Формула и отличие от 3ds Max записаны в пользовательских свойствах группы нод. Встроенный текст «ПРОЧТИ — лабораторная 10» содержит короткую памятку.',
'Все учебные пределы нод относятся к локальным координатам модели. Перемещение объекта как целого не меняет их; изменение исходной сетки в режиме редактирования меняет форму. Штатные ограничения Twist задаются относительными долями.',
'## Задания и параметры']
for task in TASKS:
    parts+=['### '+str(task['n'])+' '+task['title'],'Сцена: **'+scenes[task['n']]['scene']+'**.']
    parts.extend(str(i)+'. '+text.format(**nums) for i,text in enumerate(task['steps'],1))
    parts+=['**Отличие от 3ds Max.** '+task['note']]
    if task['n'] in [1,2,4,5,6,8,9]:
        parts+=['**Приём для показа:** выбери основной меш → «Модификаторы» → измени одно поле на небольшую величину → покажи изменение формы → Ctrl+Z. Числа в отчёте соответствуют выданному исходному состоянию.']
    elif task['n']==3:parts+=['**Приём для показа:** временно выключи второй Twist значком монитора → сравни форму → включи обратно. Дублирование создаёт независимый модификатор; его параметры можно изменить отдельно.']
    elif task['n']==7:parts+=['**Приём для показа:** выбери кадр 1 → запусти воспроизведение пробелом → останови на 30 и посмотри Phase → верни кадр 1. Ripple лежит в этапах, в финальном объекте оставлена только Wave.']
    elif task['n']==10:parts+=['**Приём для показа:** выбери собственную корзину → разверни стержни → измени Radius 0,009 → сравни отверстия → Ctrl+Z. Узлы находятся в скрытых этапах; это экземпляры сфер, поэтому .blend сохраняется компактно.']
    elif task['n']==11:parts+=['**Приём для показа:** выбери «FFD — sphere» → Tab → выдели несколько верхних точек с включённым сквозным просмотром Alt+Z → G → покажи деформацию → Ctrl+Z → Tab. Решётки регулярные; Conform to Shape не выполнялся.']
    elif task['n']==12:parts+=['**Приём для показа:** выбери сферу с 10° → в Decimate выбери угол между 0 и 10° → сравни силуэт и каркас → Ctrl+Z. Не переключай режим на Collapse: его коэффициент — другой параметр.']
parts+=['## Оптимизация — измеренные значения','| Порог | Грани до | Грани после | Вершины после |','|---|---:|---:|---:|']
for angle,x in zip([0,5,10],qa['optimize']):parts+=['| '+str(angle)+'° | '+str(x['before_faces'])+' | '+str(x['after_faces'])+' | '+str(x['after_vertices'])+' |']
parts+=['## Вопросы для подготовки','Официального списка контрольных вопросов в методичке нет. Ниже — подготовка по теме, а не приписанные методичке вопросы.']
for question,maxanswer,blanswer in QUESTIONS:parts+=['### '+question,'**3ds Max:** '+maxanswer,'**Blender:** '+blanswer]
parts+=['## Что остаётся для оформления','Титульный лист и четыре настоящих снимка интерфейса. В отчёте оставлены жёлтые поля:']
for key,text in PLACEHOLDERS.items():parts+=['- **Рис. '+str(nums[key])+':** '+text]
parts+=['## Честный объём проверки',str(len(qa['checks']))+' программных проверок пройдено после повторного открытия без встроенного Python: геометрия, скрытые этапы, камеры, свет, параметры, изменения формы, 1000 точек в каждой FFD и экземпляры узлов. Wave проверена на кадрах 1, 16, 30, 45 и 60. Рендеры просмотрены отдельно; полное ручное повторение каждого действия не заявляется.',
'Модели воронки и клеммы — учебные формы. Воронка замкнута, не является сквозным инженерным воздуховодом. Корпус фонарика не содержит электрических деталей.','Индивидуальный вариант преподаватель не выдавал, что подтверждено пользователем. Самостоятельные модели в заданиях 10 и 11 выполнены.']
(OUT/'Шпаргалка_защита_Лаба10.md').write_text('\n\n'.join(parts)+'\n',encoding='utf-8')
summary='''# Итог лабораторной 10

Номер результата — **10**, несмотря на №15 внутри исходной методички.

Готовы 12 заданий в 12 сценах `Лаба10_Blender.blend`, пошаговый `Отчет_Лаба10.docx` с 19 рисунками (15 композиций собственных рендеров и 4 поля под интерфейс) и `Шпаргалка_защита_Лаба10.md`. В самостоятельных частях созданы корзина и корпус из куба. Отдельный вариант ИДЗ преподаватель не выдавал — это подтверждено пользователем.

## Существенные отличия

- Twist, FFD/Lattice и Decimate используют штатные модификаторы Blender. Bend с физическими пределами, Taper Curve/Symmetry, Noise, Stretch Amplify, Squeeze, Ripple/Wave, Skew, Affect Region и каркасный Lattice используют открытые нодовые аналоги. Их формулы доступны в `scripts/lab10/lab10_nodes.py` и свойствах групп. Равенство чисел не названо равенством алгоритмов Autodesk.
- Noise: третий набор настроек относится к третьей сфере; Iterations — число октав, а не число повторов модификатора. Частота подобрана как 180/Scale для метрового масштаба.
- Squeeze: обратный диапазон Lower 1 / Upper 0 исправлен на Lower 0 / Upper 1 м.
- Affect Region: радиус влияния принят Falloff/100 м; позиции манипуляторов выбраны явно, поскольку точных координат в методичке нет. Воздухозаборник — замкнутая учебная воронка.
- Conform to Shape не выполнен: решётки регулярные и подогнаны по габариту. Каждая содержит 1000 точек.
- Optimize: угловой Dissolve вместо Face Thresh. Из 512 исходных граней получены 512 / 420 / 279 при 0° / 5° / 10°.
- Боковой каркас Lattice: 24 стороны выбраны самостоятельно; исходный радиус стержней 0,06 м сохранён рядом с собственной более тонкой корзиной.

## Проверка

Файл повторно открыт в Blender 5.2.1 LTS с отключённым выполнением встроенных скриптов. Пройдены CHECK_COUNT проверок: геометрия, скрытые этапы, камеры/свет, стеки и влияние параметров, пространственные решётки, экземпляры узлов и относительные пути. Фаза волн проверена на кадрах 1, 16, 30, 45, 60. EEVEE проверен пробными изображениями, иллюстрации выполнены Cycles CPU, 40 сэмплов, с денойзом. Полное ручное повторение всех шагов не выполнялось. DOCX отрендерен и проверен постранично.

## Пользователю осталось

1. Оформить титульный лист.
2. Вставить четыре настоящих снимка интерфейса: **рис. 4, 7, 11, 18**. Точные сцены, объекты, вкладки и возврат состояния указаны прямо в жёлтых полях отчёта и шпаргалке. Рендеры не названы скриншотами.

## Воспроизведение

Blender: `build_lab10.py`, затем `verify_lab10.py` и `render_lab10.py` через установленный `blender.exe --background --python-exit-code 1 --python ...`. Для проверки открытия добавлять `--disable-autoexec`. Python с Pillow и python-docx: `compose_figures10.py`, затем `make_report10.py` и `make_delivery10.py`. Скрипты предполагают запуск из структуры репозитория; временные данные создаются под `work/lab10/`.
'''.replace('CHECK_COUNT',str(len(qa['checks'])))
(OUT/'ИТОГ_Лаба10.md').write_text(summary,encoding='utf-8');print('DELIVERY_TEXT_OK')
